def props(C):
    C=np.array(C); flat=C.flatten().tolist()
    cc=Counter(flat)
    return dict(zeros=int((C==0).sum()),ndist=len(set(flat)),maxc=max(cc.values()),
                diagpal=(np.diag(C)==np.diag(C)[::-1]).all(),rowsuniq=len({tuple(r) for r in C})==3,colsuniq=len({tuple(r) for r in zip(*C)})==3)
# Verify: does rule "block whose (zeros,ndist,maxc) equals demo-target's (1,6,2)" exist uniquely in demo & test, and is it identical to O?
def select(A,v=(1,6,2)):
    hits=[]
    for i in range(A.shape[0]-2):
        for j in range(A.shape[1]-2):
            B=A[i:i+3,j:j+3]
            p=props(B)
            if (p['zeros'],p['ndist'],p['maxc'])==v: hits.append(B)
    return hits
